from sympy import sqrt, simplify

def length_of_ac():
    """For the three identical squares shown, points $A$, $B$ and $C$ are vertices, and $AB$ = $2\sqrt{5}$ cm. What is the length of $AC$, in centimeters? Express your answer in simplest radical form.

[asy]
draw((0,0)--(0,10)--(30,10)--(30,0)--cycle);
draw((10,0)--(10,10));
draw((20,0)--(20,10));
draw((0,10)--(20,0),linewidth(1));
label("$A$",(0,10),NW);
label("$B$",(20,0),S);
label("$C$",(30,0),S);
[/asy]"""
    ab = 2*sqrt(5)  # Length of AB

    # Length of AC is the diagonal of a right triangle with legs of lengths AB and AB
    ac = sqrt(2) * ab

    simplified_ac = simplify(ac)

    return simplified_ac

result = length_of_ac()
