from sympy import Rational, simplify

def pyramid_volume():
    """What is the volume of a pyramid whose base is one face of a cube of side length $2$, and whose apex is the center of the cube? Give your answer in simplest form.

[asy]
import three;
triple A,B,C,D,EE,F,G,H;
A = (0,0,0);
B = (1,0,0);
C = (1,1,0);
D= (0,1,0);
EE = (0,0,1);
F = B+EE;
G = C + EE;
H = D + EE;
O = G/2;
draw(surface(B--O--C--cycle),red,nolight);
draw(surface(C--O--D--cycle),red+white,nolight);
draw(B--C--D);
draw(B--A--D,dashed);
draw(EE--F--G--H--EE);
draw(A--EE,dashed);
draw(B--F);
draw(C--G);
draw(D--H);
draw(A--O--C,dashed);
draw(B--O--D,dashed);
dot(A); dot(B); dot(C); dot(D); dot(EE); dot(F); dot(G); dot(H); dot(O);
[/asy]"""
    # The volume of a pyramid is (Base area * Height) / 3
    # The base is a right tetrahedron, so the base area is (1/2) * base * height
    # The height of the pyramid is the side length of the cube
    volume = Rational(1, 2) * 2 * 2 * 2 / 3

    return simplify(volume)

result = pyramid_volume()
print(result)
```

