from sympy import Rational, pi, simplify

def non_shaded_area():
    """A semicircle is constructed along each side of a right triangle with legs 6 inches and 8 inches. The semicircle placed along the hypotenuse is shaded, as shown. What is the total area of the two non-shaded crescent-shaped regions? Express your answer in simplest form.

[asy]
unitsize(0.4cm);
size(101);
pair A = (0,3), B = (0,0), C = (4,0);
filldraw(A..B..C--cycle,gray(0.6),black);
draw(A--B--C);
draw(Arc(A/2,3/2,90,270)^^Arc(C/2,2,0,-180)); draw(rightanglemark(A,B,C));
[/asy]"""
    # Calculate the areas of the semicircles
    area_semicircle_leg1 = Rational(1, 2) * pi * (6/2)**2
    area_semicircle_leg2 = Rational(1, 2) * pi * (8/2)**2

    # Calculate the area of the triangle
    area_triangle = Rational(1, 2) * 6 * 8

    # Calculate the area of the shaded region (the semicircle along the hypotenuse)
    area_shaded = Rational(1, 2) * pi * (10/2)**2

    # Calculate the area of the two non-shaded crescent-shaped regions
    area_non_shaded = area_semicircle_leg1 + area_semicircle_leg2 - area_shaded - area_triangle

    return simplify(area_non_shaded)

