label("$\frac{4}{5}$",(15,-15),S);
dot((0,-22));
dot((0,-20));
dot((0,-24));
[/asy]"""
    # Initialize the sum
    sum_of_fractions = Rational(0)

    # Loop over the fractions in the 15th row
    for i in range(1, 16):
        # Add the fraction to the sum
        sum_of_fractions += Rational(i, 16)

    # Simplify the sum
    sum_of_fractions = simplify(sum_of_fractions)

    return sum_of_fractions

result = sum_of_fractions()
