from sympy import Rational

def pie_chart_angle():
    """A referendum failed by a vote of 36 No's and 24 Yes's. To make this pie chart of this result, what is the lesser measure in degrees of angle $ACB$?

[asy]
import graph;
draw(Circle((0,0),20));
draw((0,0)--(0,20));
draw((0,0)--(12,-16));
label("$A$",(0,20),N);
label("$B$",(12,-16),SE);
label("$C$",(0,0),W);
label("YES",(10,13),S);
label("NO",(-10,13),S);
label("36",(-10,10),S);
label("24",(10,10),S);
[/asy]"""
    # Number of votes for each option
    no_votes = 36
    yes_votes = 24

    # Total number of votes
    total_votes = no_votes + yes_votes

    # Calculate the percentage of votes for each option
    no_percentage = Rational(no_votes, total_votes) * 100
    yes_percentage = Rational(yes_votes, total_votes) * 100

    # Convert the percentages to degrees
    no_degrees = no_percentage * 360 / 100
    yes_degrees = yes_percentage * 360 / 100

    # The lesser degree is the degree of the option with the lower percentage
    lesser_degree = min(no_degrees, yes_degrees)

    return lesser_degree

result = pie_chart_angle()
print(result)
